window.KONU_DERIN = {
  sabir: {
    kok: { harf: "ص ب ر", anlam: "Kökün asıl anlamı “tutmak, hapsetmek, bağlamak”tır. Araplar bir kimseyi bağlayıp hedef hâline getirerek öldürmeye “sabran katl” derdi. Sabır da nefsi, sızlanmaktan, haramdan ve gevşemekten alıkoymak, onu belli bir hâlde tutmaktır. Kelime bu yüzden edilgen bir katlanmayı değil, iradeyle yapılan bir tutmayı anlatır.",
      komsu: [["Hilm", "Öfke anında kendini tutmak, karşılık vermeye gücü yettiği hâlde yumuşak davranmaktır. Sabır daha geniş bir kavramdır; hilm onun öfkeye karşı gösterilen yüzüdür."], ["Sebat", "Özellikle düşman karşısında yerinden kımıldamamaktır (Enfâl 45). Sabrın bir mücadele anındaki tezahürüdür."], ["Musâbere", "Âl-i İmrân 200'deki “sâbirû”, karşılıklı sabırda yarışmak, düşmanın sabrından daha uzun sabretmektir. Sabrın toplumsal ve rekabetçi bir boyut kazanmasıdır."]] },
    seyir: [
      ["Mekke dönemi", "Mekkî surelerde sabır emri çoğunlukla doğrudan Hz. Peygamber'e yöneltilir ve davetin zorluklarıyla ilgilidir: “Onların söylediklerine sabret ve onlardan güzel bir şekilde ayrıl” (Müzzemmil 10); “Azim sahibi peygamberlerin sabrettiği gibi sabret” (Ahkāf 35). Sabır, burada inkâr ve alay karşısında davetten vazgeçmemek demektir."],
      ["Medine dönemi", "Medine'de sabır toplumsal ve askerî bir boyut kazanır. Bakara 153-157, kıblenin değişmesi ve ilk şehitlerin ardından gelir; Enfâl 46 savaşta sabrı emreder; Âl-i İmrân 200 ise sabrı, sabırda yarışmayı ve nöbette beklemeyi bir arada sayar. Sabır bireysel bir dayanıklılıktan bir topluluğun direncine dönüşür."],
      ["Bütünde", "Kur'an'da sabır sıklıkla namazla, şükürle, takvayla ve tevekkülle birlikte anılır. Bu eşleşmeler, sabrın tek başına bir erdem olmadığını, diğer erdemleri ayakta tutan bir taşıyıcı olduğunu gösterir."]
    ],
    yakin: { ref: "Bakara 155-157", ar: "وَلَنَبْلُوَنَّكُمْ بِشَيْءٍ مِنَ الْخَوْفِ وَالْجُوعِ وَنَقْصٍ مِنَ الْأَمْوَالِ وَالْأَنْفُسِ وَالثَّمَرَاتِ ۗ وَبَشِّرِ الصَّابِرِينَ ۝ الَّذِينَ إِذَا أَصَابَتْهُمْ مُصِيبَةٌ قَالُوا إِنَّا لِلّٰهِ وَإِنَّا إِلَيْهِ رَاجِعُونَ ۝ أُولَٰئِكَ عَلَيْهِمْ صَلَوَاتٌ مِنْ رَبِّهِمْ وَرَحْمَةٌ ۖ وَأُولَٰئِكَ هُمُ الْمُهْتَدُونَ",
      tr: "Andolsun sizi biraz korku, açlık, mallardan, canlardan ve ürünlerden eksiltme ile deneyeceğiz. Sabredenleri müjdele. Onlar, başlarına bir musibet geldiğinde “Biz Allah'a aitiz ve O'na döneceğiz” derler. İşte Rablerinden salavât ve rahmet onların üzerinedir; doğru yolu bulanlar da onlardır.",
      incelikler: [
        ["“Biraz” ile denemek", "Âyet “bi-şey'in”, yani “bir şeyle, biraz” der. Müfessirler bu kelimenin, sayılan belâların ne kadar ağır olursa olsun Allah'ın gücü ve rahmeti yanında küçük olduğunu ve insanın taşıyabileceği ölçüde verildiğini ima ettiğini söyler. Belânın büyüklüğü haber verilirken bile bir teselli saklıdır."],
        ["Mülkiyet ve dönüş", "“İnnâ lillâh” cümlesi iki hakikati birlikte söyler: Kaybettiğimiz şey de biz de Allah'a aitiz; O'nun olanı geri almasında bir haksızlık yoktur. “İnnâ ileyhi râciûn” ise bu kaybın son olmadığını, her şeyin O'na döneceğini hatırlatır. Biri geçmişe, biri geleceğe bakan iki teselli."],
        ["İki yük ve bir ilave", "Hz. Ömer bu âyetler hakkında şöyle demiştir: “Ne güzel iki denk yük ve ne güzel bir ilave!” (Buhârî, ta'lîkan). İki denk yük “salavât” ve “rahmet”, ilave ise “onlar doğru yolu bulanlardır” müjdesidir. Bir kervan devesine iki yanından eşit yük konur, üstüne de bir ek yük eklenir; sabredene de böyle bir ikram vaat edilir."],
        ["Musibet anının cümlesi", "Âyet sabredenleri bir duyguyla değil, musibet anında söyledikleri bir cümleyle tanımlar. Sabır, ilk sarsıntıda dilin ve kalbin neye yöneldiğinde ortaya çıkar."]
      ] },
    tedebbur: [["Belâların “biraz” kelimesiyle anılması, yaşadığın bir zorluğa bakışını nasıl değiştirebilir?", "Bir zorluğun, Allah'ın kudreti ve rahmeti yanında ne kadar büyük olduğunu düşün; aynı zamanda onun senin taşıyabileceğin ölçüde verildiğini hatırla."], ["“Biz Allah'a aitiz” cümlesini, sahip olduğun bir şeyi düşünerek söyle. Bu cümle o şeyle ilişkini nasıl değiştiriyor?", "Bir şeye sahip olmak ile onu emanet olarak taşımak arasındaki farkı düşün."], ["Sabrın kökündeki “tutmak” anlamı, sabrı edilgen bir bekleyişten nasıl ayırıyor?", "Bugün dilini, öfkeni veya bir arzunu bilinçli olarak tuttuğun bir anı düşün."]] },

  sukur: {
    kok: { harf: "ش ك ر", anlam: "Araplar az yemle beslendiği hâlde besili görünen hayvana “şekûr” derdi. Kökün temel anlamı, verilenin karşılığını fazlasıyla göstermektir. Bu yüzden Allah'ın isimlerinden biri de “eş-Şekûr”dur (Fâtır 30, Teğâbün 17): Kulun az amelini çok mükâfatla karşılayan. Şükrün zıddı olan “küfür” (küfrân) ise “örtmek” anlamına gelir; nankör, nimeti örten ve onu sahibine nispet etmeyendir.",
      komsu: [["Hamd", "Hamd, bir varlığı kemal sıfatları için övmektir; bir nimet olmasa da yapılır. Şükür ise nimete karşılıktır, ama yalnızca dille değil, kalp ve amelle de yapılır. Bu yüzden hamd dil bakımından, şükür kapsam bakımından daha geniştir."], ["Sena", "Övgü ve iyi anıştır; şükrün dille ifade edilen yüzüdür."], ["Kanaat", "Verilene razı olmaktır. Kanaat olmadan şükür zorlaşır; çünkü insan elindekini görmeden şükredemez."]] },
    seyir: [
      ["Mekke dönemi", "Mekkî surelerde şükür, Allah'ın nimetlerini saymanın ardından gelen bir çağrıdır. Nahl suresi bu yüzden “nimetler suresi” olarak anılır: Hayvanlar, yağmur, bitkiler, deniz ve gece-gündüz sayılır, sonra “Umulur ki şükredersiniz” denir. Lokmân 12'de ise şükür, hikmetin ilk ifadesi olarak sunulur."],
      ["Medine dönemi", "Medine'de şükür zikirle (Bakara 152) ve sebatla ilişkilendirilir. Uhud'dan sonra inen Âl-i İmrân 144-145'te, Hz. Peygamber'in öldüğü haberi yayıldığında geri dönmeyip sebat edenler “şükredenler” olarak anılır: “Allah şükredenleri mükâfatlandıracaktır.” Şükür burada bir duygu değil, zor anda dini terk etmemektir."],
      ["Bütünde", "Kur'an, insanların çoğunun şükretmediğini sıkça hatırlatır (A'râf 10, Sebe' 13). Şükür, kalabalığın değil, azınlığın vasfı olarak sunulur."]
    ],
    yakin: { ref: "Lokmân 12", ar: "وَلَقَدْ آتَيْنَا لُقْمَانَ الْحِكْمَةَ أَنِ اشْكُرْ لِلّٰهِ ۚ وَمَنْ يَشْكُرْ فَإِنَّمَا يَشْكُرُ لِنَفْسِهِ ۖ وَمَنْ كَفَرَ فَإِنَّ اللّٰهَ غَنِيٌّ حَمِيدٌ",
      tr: "Andolsun biz Lokmân'a, “Allah'a şükret” diye hikmet verdik. Kim şükrederse ancak kendisi için şükreder; kim nankörlük ederse bilsin ki Allah her şeyden müstağnîdir, övülmeye layıktır.",
      incelikler: [
        ["Hikmetin ilk cümlesi", "Âyet Lokmân'a verilen hikmeti tek bir cümleyle açıklar: “Allah'a şükret.” Müfessirler buradan, hikmetin özünün nimeti tanımak ve onu sahibine nispet etmek olduğunu çıkarır. Akıllı insan, elindekinin kaynağını bilen insandır."],
        ["Şükrün faydası kime döner?", "“Kim şükrederse ancak kendisi için şükreder” ifadesindeki “innemâ” (ancak) edatı, şükrün faydasının tamamen insana döndüğünü vurgular. Allah'ın şükre ihtiyacı yoktur; şükür, insanı nimetle doğru bir ilişkiye sokarak onu korur."],
        ["İki isim", "Âyet “ğaniyy” ve “hamîd” isimleriyle biter: Allah hiçbir şeye muhtaç değildir ve kimse övmese de övülmeye layıktır. Nankörlük Allah'a bir şey eksiltmez; yalnızca nankörü bu övgüye katılmaktan mahrum bırakır."]
      ] },
    tedebbur: [["Şükrün “az olana çok karşılık vermek” anlamı, Allah'ın “Şekûr” ismiyle birlikte düşünüldüğünde sana ne hissettiriyor?", "Senin az amelinin Allah katında nasıl büyütüldüğünü ve senin de başkalarının küçük iyiliklerini büyütebileceğini düşün."], ["Âl-i İmrân 144'te şükür, zor anda sebat etmekle eşleştiriliyor. Senin hayatında şükrün en zor olduğu an hangisi?", "Bir nimetin elinden alındığı veya bir sıkıntının geldiği anda şükrün nasıl bir şekil alabileceğini düşün."], ["“Şükür hikmetin başıdır” fikri, akıllı olmayı nasıl yeniden tanımlıyor?", "Elindekinin kaynağını görmeyen bir zekâ ile onu gören bir kalbi karşılaştır."]] },

  tevekkul: {
    kok: { harf: "و ك ل", anlam: "Kök, bir işi başkasına bırakmak ve ona dayanmak anlamındadır. “Vekâlet” de buradan gelir: Vekil, adına iş görülen kişinin işini üstlenen güvenilir kimsedir. Allah'ın “el-Vekîl” ismi, kulun bütün işlerini üstlenen ve ona yeten demektir. Aynı kökten gelen “tevâkül” ise sorumluluğu başkasına yıkıp tembelce beklemektir; tevekkülün sahte bir benzeridir.",
      komsu: [["Tefvîz", "İşi tamamen Allah'a havale etmektir: “İşimi Allah'a havale ediyorum” (Mü'min 44). Tevekkülde kul sebeplere sarılır, tefvîzde ise sebeplerin bittiği yerde teslim olur."], ["Teslim", "Allah'ın hükmüne iç direnç göstermeden boyun eğmektir. Tevekkülün sonucu ve olgun hâlidir."], ["Sika", "Güvendir. Tevekkülün kalpteki temeli, Allah'ın vaadine ve hikmetine duyulan güvendir."]] },
    seyir: [
      ["Mekke dönemi", "Mekkî surelerde tevekkül, peygamberlerin kavimlerinin tehditleri karşısındaki tavrıdır. Hz. Nûh kavmine meydan okur: “Ben Allah'a tevekkül ettim; siz de ortaklarınızla birlikte işinizi toplayın” (Yûnus 71). Hz. Hûd “Ben, benim de Rabbim, sizin de Rabbiniz olan Allah'a tevekkül ettim” der (Hûd 56). Peygamberler topluca “Bize yollarımızı gösterdiği hâlde neden Allah'a tevekkül etmeyelim?” derler (İbrâhîm 12)."],
      ["Medine dönemi", "Medine'de tevekkül, istişare ve kararın ardından gelir (Âl-i İmrân 159), savaşın ertesindeki tehditler karşısında güç olur (Âl-i İmrân 173) ve barışın da bir parçasıdır: “Eğer barışa yanaşırlarsa sen de ona yanaş ve Allah'a tevekkül et” (Enfâl 61). Tevekkül hem savaşta hem barışta, sonucu belirsiz kararların manevî dayanağıdır."]
    ],
    yakin: { ref: "Âl-i İmrân 173-174", ar: "الَّذِينَ قَالَ لَهُمُ النَّاسُ إِنَّ النَّاسَ قَدْ جَمَعُوا لَكُمْ فَاخْشَوْهُمْ فَزَادَهُمْ إِيمَانًا وَقَالُوا حَسْبُنَا اللّٰهُ وَنِعْمَ الْوَكِيلُ ۝ فَانْقَلَبُوا بِنِعْمَةٍ مِنَ اللّٰهِ وَفَضْلٍ لَمْ يَمْسَسْهُمْ سُوءٌ",
      tr: "Bazı insanlar onlara “İnsanlar size karşı toplandı, onlardan korkun” dediklerinde bu, onların imanını artırdı ve “Allah bize yeter; O ne güzel vekildir” dediler. Böylece Allah'tan bir nimet ve lütufla döndüler; kendilerine hiçbir kötülük dokunmadı.",
      incelikler: [
        ["Bağlam: Yaralı bir ordu", "Âyetler Uhud'un ertesi günü yaşanan Hamrâülesed seferi hakkındadır. Hz. Peygamber, yaralı ve yorgun sahabeyle Mekke ordusunun ardından çıkmış; düşmanın yeniden saldırmak için toplandığı haberi yayılmıştı. Tevekkül, güçlü olunan bir anda değil, en zayıf anda söylenen bir cümledir."],
        ["Korkutma imanı artırdı", "Beklenen, korku haberinin sahabeyi geri çekmesiydi; âyet ise bunun imanlarını artırdığını söyler. Tehdit, iman edenin kalbinde bir dayanağa daha sıkı sarılmaya dönüşür."],
        ["Sonuç: “Dokunmadı”", "Âyet sonucu üç kelimeyle bildirir: nimet, lütuf ve hiçbir kötülüğün dokunmaması. Tevekkülün meyvesi, tehlikenin her zaman ortadan kalkması değil, kalbin ondan zarar görmemesidir."]
      ] },
    tedebbur: [["“Hasbünallah” cümlesinin, sahabenin en zayıf olduğu bir anda söylenmesi sana ne düşündürüyor?", "Güçlü olduğun anlarda değil, gücünün tükendiği anlarda neye dayandığını düşün."], ["Tevekkül ile tevâkül aynı kökten geliyor. Kendi hayatında tevekkül sandığın ama aslında tevâkül olan bir durum var mı?", "Elinden geleni yapıp yapmadığını dürüstçe sorgula."], ["Bir korku haberinin imanı artırması nasıl mümkün olur?", "Tehlike karşısında neye sığındığının, imanının gerçek ölçüsü olduğunu düşün."]] },

  adalet: {
    kok: { harf: "ع د ل · ق س ط", anlam: "“Adl” kökü eşitlemek ve denkleştirmek anlamındadır; bir devenin iki yanına konan eşit ağırlıktaki yüklere “idl” denir. Aynı kökten gelen “adl” kelimesi Kur'an'da “fidye, karşılık” anlamında da kullanılır (Bakara 48). “Kıst” kökünde ise dikkat çekici bir incelik vardır: Aynı kökten gelen “kāsit” zalim, “muksit” ise adil demektir. Kur'an, “kāsitûn”un cehennem odunu olduğunu (Cin 15), Allah'ın ise “muksitler”i sevdiğini bildirir (Hucurât 9). Kökün bir yüzü hakkı vermek, diğer yüzü hakkı çiğnemektir.",
      komsu: [["Zulüm", "Bir şeyi yerinin dışına koymaktır; adaletin zıddıdır. Şirk de bu yüzden “büyük bir zulüm” olarak anılır (Lokmân 13)."], ["İhsan", "Adaletin üstüdür: Hakkı tam vermek adalet, fazlasını vermek ihsandır. Nahl 90 ikisini yan yana emreder."], ["Mîzân", "Terazidir. Kur'an adaleti bir terazi imgesiyle de anlatır: “Göğü yükseltti ve teraziyi koydu ki tartıda haddi aşmayasınız” (Rahmân 7-8)."]] },
    seyir: [
      ["Mekke dönemi", "Mekkî âyetlerde adalet, bireysel ahlâkın ve sözün bir parçasıdır: “Söz söylediğinizde, akraba da olsa adaletli olun” (En'âm 152). Nahl 90 Mekkî olduğu hâlde, adaleti, ihsanı ve akrabaya yardımı bir arada emreden en kapsamlı âyetlerden biridir."],
      ["Medine dönemi", "Medine'de adalet bir toplum ve yönetim ilkesine dönüşür: Emanetlerin ehline verilmesi ve adaletle hükmetmek (Nisâ 58), kendi aleyhine de olsa şahitlik (Nisâ 135), düşmana karşı adalet (Mâide 8) ve çatışan iki mümin grup arasında adaletle barış yapmak (Hucurât 9). Hadîd 25 ise peygamberlerin gönderiliş amacını insanların adaleti ayakta tutması olarak açıklar."]
    ],
    yakin: { ref: "Nisâ 135", ar: "يَا أَيُّهَا الَّذِينَ آمَنُوا كُونُوا قَوَّامِينَ بِالْقِسْطِ شُهَدَاءَ لِلّٰهِ وَلَوْ عَلَىٰ أَنْفُسِكُمْ أَوِ الْوَالِدَيْنِ وَالْأَقْرَبِينَ ۚ إِنْ يَكُنْ غَنِيًّا أَوْ فَقِيرًا فَاللّٰهُ أَوْلَىٰ بِهِمَا ۖ فَلَا تَتَّبِعُوا الْهَوَىٰ أَنْ تَعْدِلُوا ۚ وَإِنْ تَلْوُوا أَوْ تُعْرِضُوا فَإِنَّ اللّٰهَ كَانَ بِمَا تَعْمَلُونَ خَبِيرًا",
      tr: "Ey iman edenler! Kendiniz, anne babanız ve yakınlarınız aleyhine de olsa, Allah için şahitlik eden kimseler olarak adaleti titizlikle ayakta tutun. Zengin de olsa fakir de olsa, Allah ikisine de daha yakındır. Adaletten sapmak için hevânıza uymayın. Eğer dilinizi eğip bükerseniz veya yüz çevirirseniz, bilin ki Allah yaptıklarınızdan haberdardır.",
      incelikler: [
        ["“Kavvâmîn”: Sürekli ayakta tutmak", "Âyet “adaletli olun” demekle yetinmez, “kavvâmîne bi'l-kıst” der. “Kavvâm” mübalağa kalıbıdır: Adaleti bir kez değil, sürekli ve titizlikle ayakta tutan kimseler. Adalet, ara sıra yapılan bir iyilik değil, bir duruştur."],
        ["Sıralama: Önce kendin", "Aleyhine şahitlik yapılabilecekler sıralanırken önce “kendiniz”, sonra anne baba, sonra yakınlar gelir. İnsanın en zor adil olduğu kişi kendisidir; âyet en zorundan başlar."],
        ["Fakire acımak da bir tuzaktır", "“Zengin de olsa fakir de olsa” ifadesi iki ayrı tehlikeye işaret eder: Zengine yaranmak için ve fakire acıdığı için adaletten sapmak. Âyet ikisini de reddeder; çünkü “Allah ikisine de daha yakındır.”"],
        ["Dili eğip bükmek", "“Telvû” fiili, şahitlikte gerçeği tamamen inkâr etmeden, kelimeleri bükerek veya önemli bir ayrıntıyı gizleyerek çarpıtmayı anlatır. “Yüz çevirmek” ise şahitlik yapmaktan kaçınmaktır. Âyet, açık yalanın yanında bu ince adaletsizlikleri de kapsar."]
      ] },
    tedebbur: [["“Kāsit” ile “muksit” kelimelerinin aynı kökten gelmesi, adalet ile zulüm arasındaki mesafenin ne kadar kısa olabileceğini nasıl gösteriyor?", "Bir hakkı vermek ile onu çiğnemenin aynı yetkiyle yapılabildiğini düşün."], ["Nisâ 135'teki sıralamaya göre önce kendine karşı adil olmak gerekir. Son zamanlarda kendi lehine “dilini eğip büktüğün” bir an oldu mu?", "Bir anlaşmazlıkta olayı anlatırken önemli bir ayrıntıyı atladığın bir durumu düşün."], ["Fakire acımanın adaleti bozabileceği uyarısı, merhamet ile adalet arasında nasıl bir denge kurmayı öğretiyor?", "Merhametin adaletin yerine değil, onun yanında olması gerektiğini düşün."]] },

  rizik: {
    kok: { harf: "ر ز ق", anlam: "Rızık, sürekli verilen paydır. Arapçada askerlere düzenli olarak verilen ödenek için de bu kelime kullanılırdı. Kur'an'da rızık yalnızca yiyecek ve mal değil, ilim, iman, evlat ve cennet nimetleri için de kullanılır: Cennetteki nimetler “kerîm bir rızık” (Enfâl 4), Allah'ın verdiği ilim ve vahiy de “güzel bir rızık” (Hûd 88) olarak anılır. Vâkıa 82'deki “Rızkınızı (ona karşı şükrü) yalanlamak mı kılıyorsunuz?” âyeti ise, yağmuru Allah yerine yıldızlara nispet edenleri kınar.",
      komsu: [["Nasîb", "Kişiye düşen paydır; rızkın bireye yönelen yüzüdür. Kasas 77'de “Dünyadan da nasibini unutma” denir."], ["Kesb", "İnsanın çabasıyla elde ettiğidir. Rızık Allah'ın vermesine, kesb insanın çalışmasına bakar."], ["Bereket", "Bir şeyde Allah'ın koyduğu artış ve hayırdır. Az bir rızık bereketle yeterli, çok bir rızık bereketsizlikle yetersiz olabilir."]] },
    seyir: [
      ["Mekke dönemi", "Mekkî surelerde rızık, Allah'ın rubûbiyetinin delili ve şükre çağrının sebebidir. Câhiliye Araplarının fakirlik korkusuyla çocuklarını öldürmesi bu dönemde yasaklanır (En'âm 151, İsrâ 31). Rızkın genişliği ve darlığının Allah'ın takdirinde olduğu, bunun bir değer ölçüsü olmadığı vurgulanır (Ra'd 26, Fecr 15-16)."],
      ["Medine dönemi", "Medine'de rızık, infak, helal ve temiz (tayyib) olanı yemek ve ticaretle ilişkilendirilir: “Size verdiğimiz rızıkların temiz olanlarından yiyin” (Bakara 172); “Namaz kılınınca yeryüzüne dağılın ve Allah'ın lütfundan arayın” (Cuma 10). Müminlerin ilk vasıflarından biri, kendilerine verilen rızıktan infak etmeleridir (Bakara 3)."]
    ],
    yakin: { ref: "En'âm 151 ve İsrâ 31", ar: "وَلَا تَقْتُلُوا أَوْلَادَكُمْ مِنْ إِمْلَاقٍ ۖ نَحْنُ نَرْزُقُكُمْ وَإِيَّاهُمْ ۝ وَلَا تَقْتُلُوا أَوْلَادَكُمْ خَشْيَةَ إِمْلَاقٍ ۖ نَحْنُ نَرْزُقُهُمْ وَإِيَّاكُمْ",
      tr: "Fakirlik sebebiyle çocuklarınızı öldürmeyin; sizi de onları da biz rızıklandırırız (En'âm 151). Fakirlik korkusuyla çocuklarınızı öldürmeyin; onları da sizi de biz rızıklandırırız (İsrâ 31).",
      incelikler: [
        ["İki âyet, iki ayrı durum", "En'âm 151'de “fakirlik sebebiyle” (min imlâk), İsrâ 31'de ise “fakirlik korkusuyla” (haşyete imlâk) denir. Birincisi şu an fakir olan, ikincisi ise şu an fakir olmadığı hâlde çocuğun gelecekte kendisini fakirleştireceğinden korkan kimseye hitap eder."],
        ["Sıralama değişiyor", "Bu farka göre rızık vaadinin sırası da değişir. Hâlihazırda fakir olana “Sizi de onları da rızıklandırırız” denir; önce onun kendi kaygısı giderilir. Gelecekten korkana ise “Onları da sizi de rızıklandırırız” denir; önce çocuğun rızkının garanti olduğu söylenir, çünkü onun korkusu çocuğun yükünden gelmektedir."],
        ["Rızık ve değer", "Müfessirler bu âyetlerden, rızkın Allah'ın elinde olduğunu ve bir insanın varlığının değerinin onun ekonomik maliyetiyle ölçülemeyeceğini çıkarır. Her doğan, rızkıyla birlikte doğar."]
      ] },
    tedebbur: [["Bir harfin yeri değişince anlamın bu kadar inceldiğini görmek, Kur'an'ı okuma dikkatini nasıl etkiliyor?", "Birbirine benzeyen iki âyeti yan yana koyup farklarını aramayı dene."], ["Gelecekle ilgili bir “fakirlik korkusu” senin kararlarını nasıl etkiliyor?", "Korkunun, şu anki gerçek ihtiyaçtan mı, yoksa geleceğe dair bir kaygıdan mı doğduğunu ayırt etmeyi düşün."], ["Kur'an'ın ilmi ve imanı da “rızık” olarak anması, rızık kavramını nasıl genişletiyor?", "Hayatındaki manevî rızıkları, maddi olanlar kadar fark edip etmediğini düşün."]] },

  takva: {
    kok: { harf: "و ق ي", anlam: "Kök korumak ve sakınmak anlamındadır; Arapça “vikāye” bir şeyi zarardan korumaktır. Takva, Kur'an'ın en merkezî kavramlarından biri olup türevleriyle iki yüz elliden fazla yerde geçer. Kur'an'ın ilk sayfasında Kur'an'ın “müttakîler için bir hidayet” olduğu bildirilir (Bakara 2); takva hem hidayetin şartı hem de meyvesidir.",
      komsu: [["Havf", "Gelecekte bir zarar beklemekten doğan genel korkudur."], ["Haşyet", "Bilgiyle birlikte gelen saygılı korkudur; Kur'an bunu âlimlere nispet eder (Fâtır 28). Korkulanın büyüklüğünü bilmekten doğar."], ["Rahbet", "Korkuyla birlikte kaçmak ve uzak durmaktır."], ["Vecel", "Kalbin ürpermesidir: “Allah anıldığında kalpleri ürperir” (Enfâl 2). Takva bu duyguların hepsini davranışa dönüştüren korunma tedbiridir."]] },
    seyir: [
      ["Mekke dönemi", "Mekkî surelerde takva çoğunlukla âhiret bilinciyle ve tevhidle birlikte anılır: Allah'tan sakınmak, O'na ortak koşmamak ve hesap gününden korkmak. Takva sahipleri için cennetin hazırlandığı müjdelenir."],
      ["Medine dönemi", "Medine'de takva, ibadetlerin ve hükümlerin amacı olarak sunulur. Oruç farz kılınırken “Umulur ki sakınırsınız” (Bakara 183), kısas hükmü bildirilirken “Umulur ki sakınırsınız” (Bakara 179) denir. Hac için “En hayırlı azık takvadır” (Bakara 197), kurban için “Allah'a ulaşan sizin takvanızdır” (Hac 37) buyrulur. Takva, ibadetin şeklinden öte, onun asıl hedefidir."]
    ],
    yakin: { ref: "Hac 37", ar: "لَنْ يَنَالَ اللّٰهَ لُحُومُهَا وَلَا دِمَاؤُهَا وَلَٰكِنْ يَنَالُهُ التَّقْوَىٰ مِنْكُمْ",
      tr: "Onların ne etleri ne de kanları Allah'a ulaşır; fakat O'na sizin takvanız ulaşır.",
      incelikler: [
        ["Câhiliye âdeti", "Müfessirler, Câhiliye döneminde Arapların kestikleri kurbanların kanını Kâbe'nin duvarlarına sürdüklerini ve etlerini oraya astıklarını nakleder. Müslümanlar da benzerini yapmak isteyince âyet indi: Allah'ın kana ve ete ihtiyacı yoktur."],
        ["“Lenyenâle”: Ulaşmak", "Âyet “kabul etmez” değil, “ulaşmaz” der. İbadetin maddi kısmı yeryüzünde kalır; Allah'a ulaşan, onun içindeki takva, yani kalbin yönelişidir."],
        ["“Minkum”: Sizden", "Takva “sizden” ulaşır. İbadet bir kurban, bir para veya bir hareket olsa da Allah'a ulaşan şey, onu yapan kişinin kendisinden çıkan bir hâldir."]
      ] },
    tedebbur: [["Her ibadetin sonunda “umulur ki sakınırsınız” denmesi, ibadetlerine bakışını nasıl değiştirebilir?", "Bir ibadeti yerine getirdikten sonra seni neyden daha çok sakındırdığını sormayı dene."], ["Hac 37'deki “ulaşmak” fiili, bugün yaptığın bir ibadetin hangi kısmının yeryüzünde kalıp hangi kısmının Allah'a ulaştığını düşünmeye nasıl davet ediyor?", "Bir sadakanın parası ile onu verirken kalbinden geçenleri ayırt etmeyi düşün."], ["Havf, haşyet ve vecel arasındaki farklar, kendi korkunun hangi türden olduğunu anlamana nasıl yardım edebilir?", "Allah'tan korkunun bir dehşet mi, yoksa bilgiden doğan bir saygı mı olduğunu düşün."]] },

  tevbe: {
    kok: { harf: "ت و ب", anlam: "Kökün anlamı “dönmek”tir. Kur'an bu kelimeyi hem kul hem de Allah için kullanır: Kul günahtan Allah'a döner (tâbe ilâllâh), Allah da rahmetiyle kula döner (tâbe aleyh). Allah'ın ismi “et-Tevvâb”, tevbeleri tekrar tekrar kabul eden ve kullarına sürekli rahmetle dönen demektir. Tevbe böylece iki taraflı bir dönüştür: Kulun Allah'a dönüşü ile Allah'ın kula dönüşü.",
      komsu: [["İstiğfar", "Bağışlanma dilemektir. Kökü “ğafr”, örtmek demektir; savaşta başı koruyan miğfer de buradan gelir. İstiğfar, günahın hem örtülmesini hem de zararından korunmayı istemektir."], ["İnâbe", "Sürekli yönelmek ve geri dönmektir. Tevbe günahtan dönmek, inâbe ise kalbin her an Allah'a yönelik olmasıdır."], ["Evbe", "Dönmek ve yönelmektir; Hz. Dâvûd ve Hz. Süleyman “evvâb” (çokça Allah'a dönen) olarak övülür (Sâd 17, 30)."]] },
    seyir: [
      ["Mekke dönemi", "Mekkî surelerde tevbe, en büyük günahları işleyenlere bile açık bir kapı olarak sunulur: “Ey kendilerine karşı haddi aşan kullarım! Allah'ın rahmetinden ümit kesmeyin” (Zümer 53). Furkān 68-70'te şirk, cinayet ve zina sayıldıktan sonra tevbe edenlerin kötülüklerinin iyiliklere çevrileceği müjdelenir."],
      ["Medine dönemi", "Medine'de tevbe toplumsal bir boyut kazanır: “Ey müminler! Hepiniz Allah'a tevbe edin” (Nûr 31). Tebük seferinden geri kalan üç sahabinin tevbesi bir surenin adı hâline gelir (Tevbe 118) ve “nasûh”, yani içten ve kesin bir tevbe emredilir (Tahrîm 8)."]
    ],
    yakin: { ref: "Tevbe 118", ar: "وَعَلَى الثَّلَاثَةِ الَّذِينَ خُلِّفُوا حَتَّىٰ إِذَا ضَاقَتْ عَلَيْهِمُ الْأَرْضُ بِمَا رَحُبَتْ وَضَاقَتْ عَلَيْهِمْ أَنْفُسُهُمْ وَظَنُّوا أَنْ لَا مَلْجَأَ مِنَ اللّٰهِ إِلَّا إِلَيْهِ ثُمَّ تَابَ عَلَيْهِمْ لِيَتُوبُوا ۚ إِنَّ اللّٰهَ هُوَ التَّوَّابُ الرَّحِيمُ",
      tr: "Geri bırakılan o üç kişinin de tevbesini kabul etti. Yeryüzü bütün genişliğine rağmen onlara dar gelmiş, nefisleri de kendilerine dar gelmişti. Allah'tan, yine O'na sığınmaktan başka bir sığınak olmadığını anlamışlardı. Sonra Allah, tevbe etsinler diye onların tevbesini kabul etti. Şüphesiz Allah tevbeleri çokça kabul eden, çok merhametli olandır.",
      incelikler: [
        ["Ka'b b. Mâlik'in dürüstlüğü", "Bu üç kişiden biri olan Ka'b b. Mâlik, Tebük'ten dönen Hz. Peygamber'e diğer geri kalanlar gibi bir bahane uydurmadı; mazeretinin olmadığını açıkça söyledi. Sonra elli gün boyunca kimse onlarla konuşmadı. Ka'b sonradan şöyle demiştir: “Allah'ın bana İslâm'dan sonra verdiği en büyük nimet, Resûlullah'a doğruyu söylememdir; yalan söyleseydim, yalan söyleyenler gibi helak olurdum” (Buhârî, Müslim)."],
        ["İki darlık", "Âyet iki darlıktan söz eder: Yeryüzünün “bütün genişliğine rağmen” dar gelmesi ve insanın kendi nefsinin kendisine dar gelmesi. Dışarıdaki dünya ne kadar geniş olursa olsun, içi daralan insana yer kalmaz."],
        ["Allah'tan Allah'a kaçmak", "“Allah'tan, yine O'na sığınmaktan başka bir sığınak yoktur” cümlesi, kaçılacak tek yerin, kendisinden kaçılan olduğunu söyler. Tevbe, cezadan korkup Allah'tan uzaklaşmak değil, O'nun rahmetine kaçmaktır."],
        ["Önce Allah döndü", "“Tevbe etsinler diye Allah onlara tevbe etti” ifadesinde Allah'ın tevbesi kulun tevbesinden önce gelir. Müfessirler bunu şöyle açıklar: Allah önce kula tevbe etme muvaffakiyetini verdi, sonra kul tevbe etti. Kulun dönüşü bile Allah'ın bir dönüşünün sonucudur."]
      ] },
    tedebbur: [["Ka'b'ın “doğruyu söylemem en büyük nimetti” demesi, bir hatayı kabul etmenin bedeli ve meyvesi hakkında sana ne söylüyor?", "Bir hatanı bahane bulmadan kabul ettiğin bir anı ve sonrasını düşün."], ["“Nefislerinin kendilerine dar gelmesi” hâlini hiç yaşadın mı? O darlıktan nasıl çıktın?", "İçindeki darlığın, dışarıdaki imkânlarla değil, bir dönüşle genişleyebileceğini düşün."], ["Allah'ın tevbesinin kulun tevbesinden önce gelmesi, tevbe etmek isteyip edemediğin anlarda sana nasıl bir ümit veriyor?", "Tevbe etme isteğinin kendisinin bile bir ilâhî davet olabileceğini düşün."]] },

  rahmet: {
    kok: { harf: "ر ح م", anlam: "Rahmet kelimesi, ana rahmini anlatan “rahim” ile aynı köktendir. Bir hadis-i kudsîde Allah şöyle buyurur: “Ben Rahmân'ım. Rahmi (akrabalık bağını) ben yarattım ve ona kendi ismimden bir isim verdim. Onu gözeteni ben de gözetirim, onu keseni ben de keserim” (Ebû Dâvûd, Tirmizî). Rahmetin en somut imgesi, bir annenin rahminde çocuğu kuşatması ve beslemesidir; akrabalık bağı da bu yüzden rahmetin yeryüzündeki yansıması sayılır.",
      komsu: [["Re'fet", "Acıma ve şefkattir; rahmetten daha incedir. Nûr 2'de “Allah'ın dininde onlara acımanız (re'fet) sizi tutmasın” denir; yani yersiz bir acıma adaleti engelleyebilir."], ["Hanân", "Derin bir şefkat ve sevecenliktir; Hz. Yahyâ'ya “katımızdan bir hanân” verildiği bildirilir (Meryem 13)."], ["Şefkat", "Birinin zarar görmesinden kaygı duymaktır; rahmetin koruyucu yüzüdür."]] },
    seyir: [
      ["Mekke dönemi", "Mekkî surelerde rahmet, Allah'ın kendisine yazdığı bir ilke olarak iki kez tekrarlanır (En'âm 12, 54). Kur'an'ın kendisi de bir rahmet olarak sunulur (Yûnus 57-58) ve rahmetin her şeyi kuşattığı bildirilir (A'râf 156). Hz. Peygamber'in âlemlere rahmet olarak gönderildiği de Mekkî bir surede yer alır (Enbiyâ 107)."],
      ["Medine dönemi", "Medine'de rahmet, toplum ilişkilerinin ilkesi hâline gelir: Hz. Peygamber'in yumuşaklığı Allah'ın rahmetinin bir sonucudur (Âl-i İmrân 159); müminler “kendi aralarında merhametli”dir (Fetih 29). Rahmet, bir ilâhî sıfat olmaktan bir toplumun karakterine dönüşür."]
    ],
    yakin: { ref: "En'âm 54", ar: "وَإِذَا جَاءَكَ الَّذِينَ يُؤْمِنُونَ بِآيَاتِنَا فَقُلْ سَلَامٌ عَلَيْكُمْ ۖ كَتَبَ رَبُّكُمْ عَلَىٰ نَفْسِهِ الرَّحْمَةَ ۖ أَنَّهُ مَنْ عَمِلَ مِنْكُمْ سُوءًا بِجَهَالَةٍ ثُمَّ تَابَ مِنْ بَعْدِهِ وَأَصْلَحَ فَأَنَّهُ غَفُورٌ رَحِيمٌ",
      tr: "Âyetlerimize iman edenler sana geldiğinde onlara de ki: “Selâm size! Rabbiniz rahmeti kendisine yazdı. Sizden kim bilmeyerek bir kötülük yapar, sonra arkasından tevbe edip durumunu düzeltirse, şüphesiz O çok bağışlayan, çok merhamet edendir.”",
      incelikler: [
        ["Kime selam verilecek?", "Âyet, Mekke'nin ileri gelenlerinin Hz. Peygamber'in yanından uzaklaştırılmasını istediği fakir ve zayıf müminler hakkındadır. Onları kovmak yerine onlara selam vermesi ve rahmeti müjdelemesi emredilir. İlâhî rahmetin ilk müjdesi, toplumun dışladıklarına verilir."],
        ["“Kendisine yazdı”", "Allah'ın rahmeti “kendi üzerine yazması”, kelâmcıların üzerinde durduğu bir ifadedir. Ehl-i sünnete göre Allah'a hiçbir şey dışarıdan vacip kılınamaz; bu, Allah'ın kendi lütfuyla kendi üzerine aldığı bir vaattir. Rahmet, Allah'ın bir zorunluluğu değil, kendi seçtiği bir taahhüdüdür."],
        ["“Bilmeyerek”", "“Bi-cehâletin” ifadesini müfessirler, yalnızca bilgisizlik olarak değil, günah işleyen her insanın o anda bir tür câhillik içinde olması, yani sonucunu düşünmeden hareket etmesi olarak yorumlar. Bu yüzden her günahkâr bu âyetin kapsamına girer."]
      ] },
    tedebbur: [["Rahmetin ilk müjdesinin toplumun dışladıklarına verilmesi, senin çevrendeki “dışlananlara” nasıl bakmanı öneriyor?", "Bir toplulukta en az önemsenen kişiye bu hafta nasıl bir selam veya ilgi gösterebileceğini düşün."], ["Rahmet ile rahim kelimelerinin aynı kökten gelmesi, akrabalık bağlarını gözetmeyi nasıl bir ibadet hâline getiriyor?", "Uzun zamandır görüşmediğin bir akrabanı düşün."], ["Allah'ın rahmeti “kendi üzerine yazması”, günahlarına bakışını nasıl etkiliyor?", "Rahmetin bir hak değil, bir lütuf olduğunu, ama kesin bir vaat olduğunu birlikte düşün."]] },

  ilim: {
    kok: { harf: "ع ل م", anlam: "Kökün asıl anlamı “işaret, alâmet”tir; bir şeyi diğerlerinden ayıran belirti. İlim, işaretler aracılığıyla bir şeyi bilmektir. “Âlem” kelimesi de aynı kökten gelir: Kâinat, kendisiyle Allah'ın bilindiği bir işaretler bütünüdür. Bu yüzden “âlemlerin Rabbi” ifadesi, varlıkların her birinin O'nu gösteren bir işaret olduğunu da ima eder.",
      komsu: [["Marifet", "Bir şeyi tecrübeyle, izleriyle tanımaktır. Önce bilinmeyen bir şeyin sonradan tanınmasını ima ettiği için Allah için “ârif” denmez, “âlim” denir."], ["Fıkıh", "Bir sözün derin anlamını kavramaktır. Kur'an'da “yefkahûn” (derinlemesine anlarlar) fiili sıkça geçer; fıkıh ilmi adını buradan alır."], ["Hikmet", "İlmin doğru yerde ve doğru şekilde kullanılmasıdır; bilgi ile davranışın birleşmesidir."]] },
    seyir: [
      ["Mekke dönemi", "İlk vahiy “Oku!” emriyle başlar ve ilk beş âyette “öğretmek” fiili iki kez geçer (Alak 4-5). Mekkî surelerde ilim, Allah'ı tanımanın ve O'ndan haşyet duymanın yolu olarak sunulur (Fâtır 28, Zümer 9). Hz. Peygamber'e “Rabbim, ilmimi artır” diye dua etmesi emredilir (Tâhâ 114)."],
      ["Medine dönemi", "Medine'de ilim bir toplumsal derece ve sorumluluk hâline gelir: “Allah, sizden iman edenleri ve kendilerine ilim verilenleri derecelerle yükseltir” (Mücâdele 11). Borç âyeti yazmayı ve yazı bilenin bilmeyene yazmasını emreder (Bakara 282). Tevbe 122 ise herkes savaşa çıkmışken bir grubun dinde derin bilgi edinmek için kalmasını ister."]
    ],
    yakin: { ref: "Tâhâ 114", ar: "فَتَعَالَى اللّٰهُ الْمَلِكُ الْحَقُّ ۗ وَلَا تَعْجَلْ بِالْقُرْآنِ مِنْ قَبْلِ أَنْ يُقْضَىٰ إِلَيْكَ وَحْيُهُ ۖ وَقُلْ رَبِّ زِدْنِي عِلْمًا",
      tr: "Gerçek hükümdar olan Allah yücedir. Sana vahyi tamamlanmadan önce Kur'an'ı okumakta acele etme ve “Rabbim, ilmimi artır” de.",
      incelikler: [
        ["Tek “artır” duası", "İbn Hacer, Fethu'l-bârî'nin ilim bölümünde şuna dikkat çeker: Allah, peygamberine ilimden başka hiçbir şeyin artırılmasını istemesini emretmemiştir. Bir peygamberin bile istemesi gereken tek artış ilimdir."],
        ["Acele etmemek", "Duanın hemen öncesinde Hz. Peygamber'e, vahiy tamamlanmadan onu tekrar etmekte acele etmemesi söylenir. İlim artışının ilk şartı, sabırla dinlemek ve öğrenilenin tamamlanmasını beklemektir. Kıyâme 16-19'da da aynı edep öğretilir."],
        ["Hükümdarın huzurunda", "Âyet Allah'ı “gerçek hükümdar” (el-Melikü'l-Hak) olarak anarak başlar. İlim, gerçek hükümdarın huzurunda edeple istenen bir ikramdır; kişinin kendi zekâsıyla elde ettiği bir mülk değildir."]
      ] },
    tedebbur: [["Bir peygambere bile istemesi emredilen tek artışın ilim olması, senin dualarındaki önceliklere nasıl bir ayna tutuyor?", "Bugün Allah'tan en çok neyin artmasını istediğini düşün."], ["“Âlem” kelimesinin “işaret” anlamındaki kökten gelmesi, çevrene bakışını nasıl değiştirebilir?", "Bugün gördüğün bir varlığı, neyi gösteren bir işaret olarak okuyabileceğini düşün."], ["İlimde “acele etmemek” senin öğrenme alışkanlıklarında neye karşılık geliyor?", "Bir konuyu tam öğrenmeden hüküm verdiğin veya konuştuğun anları düşün."]] },

  ahiret: {
    kok: { harf: "أ خ ر", anlam: "“Âhiret” kelimesi “sonra gelen, son” anlamındadır. Karşıtı olan “dünya” ise “yakın, alçak” anlamındaki “dünüv” kökünden gelir. Bu iki kelime, iki hayatın niteliğini de anlatır: Dünya yakındır ve göze daha çekici görünür, ama aşağıdadır; âhiret ise sonra gelir, ama asıl ve kalıcı olandır. Ankebût 64'te âhiret yurdunun “hayvân”, yani gerçek ve dolu dolu hayat olduğu söylenir.",
      komsu: [["Kıyamet", "Ölülerin dirilip kalkmasıdır; âhiretin başlangıç anı."], ["Ba's ve nüşûr", "Ölüleri diriltip kabirlerinden çıkarmaktır."], ["Kur'an'daki isimler", "Kur'an kıyameti birçok isimle anar: el-Ğâşiye (kuşatan), el-Kāria (kapıyı çalarcasına vuran), el-Hâkka (kesin gerçekleşecek olan), et-Tâmme (her şeyi örten büyük felaket), es-Sâhha (kulakları sağır eden ses). Kurtubî et-Tezkire'de bu isimleri toplar. Her isim, o günün bir başka yüzünü gösterir."]] },
    seyir: [
      ["Mekke dönemi", "Âhiret, Mekkî surelerin ana konularından biridir. Kısa surelerin büyük bir kısmı kıyametin dehşetini, dirilişi ve hesabı anlatır. Bu surelerde âhiret, inkârcılara karşı aklî delillerle ve çarpıcı tasvirlerle ispat edilir."],
      ["Medine dönemi", "Medine'de âhiret, bir ispat konusu olmaktan çok hükümlerin ve amellerin gerekçesi hâline gelir. Pek çok hüküm âyeti “Allah'a ve âhiret gününe iman edenler” ifadesiyle desteklenir. Âlimlerin önemli bir kısmına göre en son inen âyet de bir âhiret hatırlatmasıdır (Bakara 281)."]
    ],
    yakin: { ref: "Bakara 281", ar: "وَاتَّقُوا يَوْمًا تُرْجَعُونَ فِيهِ إِلَى اللّٰهِ ۖ ثُمَّ تُوَفَّىٰ كُلُّ نَفْسٍ مَا كَسَبَتْ وَهُمْ لَا يُظْلَمُونَ",
      tr: "Allah'a döndürüleceğiniz günden sakının. Sonra herkese kazandığının karşılığı tam olarak verilir ve onlara asla haksızlık edilmez.",
      incelikler: [
        ["Kur'an'ın son sözü", "İbn Abbâs'tan, Kur'an'dan en son inen âyetin bu olduğu nakledilir; Hz. Peygamber'in bu âyetin inişinden kısa bir süre sonra vefat ettiği de rivayet edilir. Yirmi üç yıllık vahyin son cümlesi, insana dönüşü ve hesabı hatırlatır."],
        ["Ribâ âyetlerinden sonra", "Âyet, ribâyı yasaklayan ve borçlu darda ise ona süre tanımayı emreden âyetlerin hemen ardından gelir. Âhiret hatırlatması, en somut ekonomik hükümlerin bile asıl gerekçesidir: Mal burada kalır, insan Allah'a döner."],
        ["“Tam ödenir”", "“Tüveffâ” fiili, bir hakkın eksiksiz ödenmesini anlatır. Aynı kökten gelen “vefat” kelimesi de ölümün, ömrün eksiksiz tamamlanması olduğunu ima eder. Hesap günü hiçbir amel eksik veya fazla tartılmaz."]
      ] },
    tedebbur: [["Kur'an'ın son inen âyetinin bir âhiret hatırlatması olması, sence neden anlamlı?", "Bütün hükümlerin ve öğütlerin sonunda insanın neyle baş başa kalacağını düşün."], ["“Dünya” kelimesinin “yakın ve aşağı” anlamı, gündelik tercihlerinde yakın olanı uzak olana tercih ettiğin anları nasıl açıklıyor?", "Hemen elde edilen bir zevk ile sonra gelecek kalıcı bir hayrı karşılaştırdığın bir kararı düşün."], ["Âhiretin “gerçek hayat” (hayvân) olarak anılması, hayat kavramını nasıl değiştiriyor?", "Şu anki hayatının, gerçek hayatın bir hazırlığı olarak nasıl yaşanabileceğini düşün."]] },

  emanet: {
    kok: { harf: "أ م ن", anlam: "Emanet kelimesi “güven” anlamındaki “emn” kökünden gelir. İman, emanet ve emniyet aynı kökün dallarıdır. “Mümin” kelimesi hem “inanan” hem de “güven veren” demektir; Allah'ın isimlerinden biri de “el-Mü'min”dir (Haşr 23). Hz. Peygamber de mümini şöyle tanımlar: “Mümin, insanların canları ve malları konusunda kendisinden emin oldukları kimsedir” (Tirmizî, Nesâî). İman ile güvenilir olmak aynı kökten beslenir.",
      komsu: [["Ahd", "Verilen söz ve yüklenilen taahhüttür. Kur'an emanet ile ahdi çoğunlukla birlikte anar (Mü'minûn 8)."], ["Vedîa", "Fıkıhta, korunması için birine bırakılan maldır. Emanet daha geniş bir kavramdır: Her vedîa bir emanettir, ama her emanet bir vedîa değildir."], ["Hıyânet", "Emanete ihanettir; emanetin zıddıdır. “Bile bile Allah'a ve Peygamber'e ihanet etmeyin ve emanetlerinize ihanet etmeyin” (Enfâl 27)."]] },
    seyir: [
      ["Mekke dönemi", "Mekkî surelerde emanete riayet, kurtuluşa eren müminlerin vasıflarından biri olarak sayılır: “Onlar emanetlerine ve ahitlerine riayet ederler” (Mü'minûn 8; Meâric 32). Bu dönemde emanet daha çok bireysel bir ahlâk ve güvenilirlik meselesidir."],
      ["Medine dönemi", "Medine'de emanet, siyasi ve toplumsal bir ilke hâline gelir: Görevlerin ehline verilmesi (Nisâ 58), emanetlere ihanet etmemek (Enfâl 27) ve borçta rehin alınmadan güvenilen kişinin emanetini ödemesi (Bakara 283). Ahzâb 72 ise emaneti insanın varoluşsal yükü olarak tanımlar."]
    ],
    yakin: { ref: "Ahzâb 72", ar: "إِنَّا عَرَضْنَا الْأَمَانَةَ عَلَى السَّمَاوَاتِ وَالْأَرْضِ وَالْجِبَالِ فَأَبَيْنَ أَنْ يَحْمِلْنَهَا وَأَشْفَقْنَ مِنْهَا وَحَمَلَهَا الْإِنْسَانُ ۖ إِنَّهُ كَانَ ظَلُومًا جَهُولًا",
      tr: "Biz emaneti göklere, yere ve dağlara sunduk; onlar onu yüklenmekten kaçındılar ve ondan korktular. İnsan ise onu yüklendi. Şüphesiz o çok zalim, çok cahildir.",
      incelikler: [
        ["“Kaçındılar”: İsyan değil, korku", "Göklerin, yerin ve dağların emaneti yüklenmekten kaçınması bir isyan değildir; âyet bunun sebebini “ondan korktular” (eşfakne) diye açıklar. Onlar emanetin ağırlığını bildikleri için ondan çekindiler."],
        ["Mübalağa kalıpları", "“Zalûm” ve “cehûl” kelimeleri “zâlim” ve “câhil”den daha güçlü, mübalağa kalıplarıdır. Bazı müfessirler bunları bir kınamadan çok bir kapasite tasviri olarak okur: Zulüm ve cehalete bu kadar büyük bir yatkınlığı olan bir varlık, aynı ölçüde büyük bir adalet ve ilim kapasitesine de sahiptir. Emaneti yüklenebilmesinin sebebi de budur."],
        ["Sonraki âyet", "Hemen ardından gelen âyet, emanetin bir imtihan olduğunu gösterir: Allah bu emanet sebebiyle münafıkları ve müşrikleri cezalandıracak, müminlerin tevbesini kabul edecektir (Ahzâb 73). Emaneti yüklenmek, hem en büyük şerefin hem de en büyük riskin kapısıdır."]
      ] },
    tedebbur: [["“Mümin” kelimesinin hem “inanan” hem de “güven veren” anlamına gelmesi, imanını başkalarının sana duyduğu güvenle nasıl ilişkilendiriyor?", "Çevrendeki insanların sana ne kadar güvenebildiğini dürüstçe düşün."], ["“Zalûm ve cehûl” sıfatlarını bir kapasite tasviri olarak okumak, insana bakışını nasıl değiştirir?", "İnsanın en kötüsüne de en iyisine de yatkın olmasının, onun sorumluluğunu nasıl büyüttüğünü düşün."], ["Göklerin ve dağların ağırlığından korktuğu bir emaneti insanın yüklenmesi, sende nasıl bir duygu uyandırıyor?", "Kendi hayatındaki sorumlulukları, bu varoluşsal emanetin parçaları olarak düşünmeyi dene."]] },

  kalp: {
    kok: { harf: "ق ل ب · ف أ د", anlam: "“Kalb” kelimesi “bir şeyi çevirmek, ters yüz etmek” anlamındaki kökten gelir; kalp, bir hâlden bir hâle dönen bir merkezdir. Kur'an'ın kalp için kullandığı bir diğer kelime olan “fuâd” ise “tutuşmak, yanmak” anlamındaki “fe'd” kökünden gelir; kalbin duygularla yanan, heyecanlanan yüzüdür. Hz. Mûsâ'yı nehre bırakan annesinin hâli “Mûsâ'nın annesinin fuâdı bomboş oldu” (Kasas 10) diye anlatılır.",
      komsu: [["Sadr", "Göğüstür; kalbin içinde bulunduğu ve duyguların genişleyip daraldığı yerdir: “Göğsünü açmadık mı?” (İnşirâh 1)."], ["Lübb", "Bir şeyin özü, çekirdeğidir. “Ülü'l-elbâb”, yani akıl ve öz sahipleri, Kur'an'ın öğüt alanlarıdır."], ["Nefs", "İnsanın arzu ve benliğidir. Kalp yönelişin, nefs ise isteklerin merkezi olarak anılır."]] },
    seyir: [
      ["Mekke dönemi", "Mekkî surelerde kalp, inkârcıların hakikati anlamamasının sebebi olarak sıkça anılır: Kalplerinin üzerinde örtüler (ekinne) olduğu (En'âm 25, Kehf 57), kalplerinin kör olduğu (Hac 46) ve paslandığı (Mutaffifîn 14) söylenir. Aynı dönemde müminlerin kalbi, Allah'ı anmakla huzur bulan bir kalp olarak tasvir edilir (Ra'd 28)."],
      ["Medine dönemi", "Medine'de kalbin “hastalığı” özellikle münafıklar için kullanılır (Bakara 10). Bunun yanında kalplerin birleştirilmesi (te'lîf) bir ilâhî nimet olarak öne çıkar: Yıllarca birbirine düşman olan Evs ve Hazrec'in kalplerinin birleştirilmesi (Enfâl 63; Âl-i İmrân 103) ve gönülleri İslâm'a ısındırılacak olanlar (müellefe-i kulûb) için zekâtta bir pay ayrılması (Tevbe 60)."]
    ],
    yakin: { ref: "Enfâl 63", ar: "وَأَلَّفَ بَيْنَ قُلُوبِهِمْ ۚ لَوْ أَنْفَقْتَ مَا فِي الْأَرْضِ جَمِيعًا مَا أَلَّفْتَ بَيْنَ قُلُوبِهِمْ وَلَٰكِنَّ اللّٰهَ أَلَّفَ بَيْنَهُمْ ۚ إِنَّهُ عَزِيزٌ حَكِيمٌ",
      tr: "Onların kalplerini birleştiren de O'dur. Sen yeryüzündeki her şeyi harcasaydın, onların kalplerini birleştiremezdin; fakat Allah onların arasını birleştirdi. Şüphesiz O mutlak güç sahibidir, hüküm ve hikmet sahibidir.",
      incelikler: [
        ["Bağlam: Evs ve Hazrec", "Müfessirler âyetin, İslâm'dan önce yüz yıldan fazla süren savaşlarla birbirine düşman olan Medine'nin iki kabilesi Evs ve Hazrec hakkında olduğunu söyler. Bu iki kabile İslâm'la kardeş olmuştur."],
        ["Mal kalpleri birleştiremez", "“Yeryüzündeki her şeyi harcasaydın” ifadesi, kalplerin birleşmesinin maddi araçlarla satın alınamayacağını söyler. Mal bir ittifak kurabilir, ama kalpleri birleştiremez."],
        ["Kalplerden araya", "Âyet önce “kalplerini birleştirdi”, sonra “aralarını birleştirdi” der. Kalplerdeki birlik, insanlar arasındaki ilişkilere yansıyan bir birliğe dönüşür."]
      ] },
    tedebbur: [["Kalbin “dönen” bir şey, fuâdın ise “yanan” bir şey olarak anlatılması, kendi iç dünyanı nasıl tarif etmene yardım ediyor?", "Kalbinin son günlerde hangi hâlden hangi hâle döndüğünü düşün."], ["Kalplerin birleşmesinin satın alınamaması, bozulmuş bir ilişkiyi onarmaya çalışırken neyi hatırlatıyor?", "Bir küskünlüğü hediye veya iyilikle değil, kalpten bir yönelişle aşmanın yolunu düşün."], ["Kalbin üzerindeki “örtüler” ve “pas” imgeleri, senin bir hakikati anlamakta zorlandığın anları nasıl açıklıyor?", "Bir uyarıyı duyduğun hâlde etkilenmediğin bir anı düşün."]] },

  dua: {
    kok: { harf: "د ع و", anlam: "Kökün anlamı “çağırmak”tır. Dua, davet ve hatta “dâvâ” (iddia) kelimeleri aynı kökten gelir. Kur'an'da bu kelime farklı anlamlarda kullanılır: ibadet etmek (“Rabbiniz ‘Bana dua edin’ dedi”, Mü'min 60), birini çağırmak, bir şey istemek ve seslenmek. Dua, kulun Rabbini çağırması, aynı zamanda Rabbin de kulu kendisine çağırmasıdır: “Allah esenlik yurduna davet eder” (Yûnus 25).",
      komsu: [["Nidâ", "Yüksek sesle seslenmektir."], ["Münâcât", "Gizli ve içten konuşmaktır; “necvâ” (fısıltı) ile aynı köktendir."], ["Tazarru", "Kendini küçültüp boyun eğerek, yalvararak dua etmektir (A'râf 55)."], ["İbtihâl", "Bütün içtenlikle, elleri açarak yalvarmaktır."]] },
    seyir: [
      ["Mekke dönemi", "Mekkî surelerde peygamberlerin duaları geniş yer tutar. Enbiyâ suresi bir dua silsilesi gibidir: Nûh'un, Eyyûb'un, Yûnus'un ve Zekeriyyâ'nın duaları art arda gelir ve her birinin ardından “Biz onun duasını kabul ettik” denir (Enbiyâ 76-90)."],
      ["Medine dönemi", "Medine'de dua, ibadetlerle ve topluluğun duasıyla birlikte anılır. Bakara 186, oruç âyetlerinin tam ortasında yer alır. Bakara suresinin son âyeti ve Âl-i İmrân'ın sonundaki dualar, müminlerin topluca, “Rabbimiz” diye yaptıkları dualardır (Bakara 286; Âl-i İmrân 191-194)."]
    ],
    yakin: { ref: "Bakara 186", ar: "وَإِذَا سَأَلَكَ عِبَادِي عَنِّي فَإِنِّي قَرِيبٌ ۖ أُجِيبُ دَعْوَةَ الدَّاعِ إِذَا دَعَانِ ۖ فَلْيَسْتَجِيبُوا لِي وَلْيُؤْمِنُوا بِي لَعَلَّهُمْ يَرْشُدُونَ",
      tr: "Kullarım sana beni sorduklarında, şüphesiz ben çok yakınım. Bana dua edince, dua edenin duasına cevap veririm. O hâlde onlar da benim davetime cevap versinler ve bana iman etsinler ki doğru yolu bulsunlar.",
      incelikler: [
        ["“De ki” yok", "Bakara suresinde “Sana soruyorlar...” diye başlayan âyetlerde cevap hep “De ki” (kul) emriyle gelir: hilaller (189), infak (215, 219), haram ay (217), içki ve kumar (219), yetimler (220), hayız (222). Bu âyette ise “De ki” yoktur; Allah doğrudan “Ben yakınım” diye cevap verir. Dua edenle Allah arasına, Peygamber bile aracı olarak girmez."],
        ["Oruç âyetlerinin ortasında", "Âyet, oruçla ilgili âyetlerin (183-187) tam ortasında yer alır. Müfessirler bundan, oruçlunun duasının kabule daha yakın olduğu ve Ramazan'ın bir dua mevsimi olduğu sonucunu çıkarır."],
        ["İki yönlü icabet", "Allah önce “Duaya cevap veririm” der, sonra “Onlar da benim davetime cevap versinler” der. Dua karşılıklı bir çağrıdır: Kul Allah'ı çağırır, Allah da kulu kendisine itaate ve imana çağırır."]
      ] },
    tedebbur: [["Bakara 186'da “De ki” emrinin olmaması, dua ederken Allah'ın sana ne kadar yakın olduğunu nasıl hissettiriyor?", "Dua ederken araya hiçbir aracı koymadan doğrudan konuştuğunu düşün."], ["Duanın kökünün “çağırmak” olması ve Allah'ın da seni çağırması, duanı tek yönlü bir istek olmaktan nasıl çıkarıyor?", "Senin dualarına karşılık Allah'ın senden neyi istediğini düşün."], ["Peygamberlerin dualarındaki tavrı (Eyyûb'un “Bana dert dokundu, sen merhametlilerin en merhametlisisin” demesi gibi) kendi dualarınla karşılaştır.", "İsteğini dile getirirken Allah'ın isimlerine ve sıfatlarına başvurmanın edebini düşün."]] },

  imtihan: {
    kok: { harf: "ب ل و · ف ت ن", anlam: "Kur'an imtihanı iki ana kökle anlatır. “Belâ” kelimesinin kökü bir şeyin eskimesi ve yıpranmasıdır; eski elbiseye “bâlî” denir. Belâ, insanı yıpratan ve içini ortaya çıkaran bir denemedir. “Fitne” ise bir madenin, katkılarından arınması için ateşe sokulmasını anlatan bir kökten gelir; Zâriyât 13'te “Onların ateşe sunulacakları gün” diye bu anlamda kullanılır. Kur'an'da fitne kelimesi, bu temel anlamdan yola çıkarak imtihan, sapkınlık, kargaşa ve işkence anlamlarında da kullanılır.",
      komsu: [["Temhîs", "Arındırmak, katkıdan ayırmaktır (Âl-i İmrân 141). İmtihanın müminler için sonucudur."], ["Temyîz", "Ayırt etmektir: “Allah pis olanı temiz olandan ayırmak için” (Âl-i İmrân 179)."], ["İbtilâ", "Denemektir; hem iyilikle hem kötülükle yapılır."]] },
    seyir: [
      ["Mekke dönemi", "Mekkî surelerde imtihan, eziyet gören ilk müminlerin tecrübesiyle iç içedir: “İnsanlar, ‘İman ettik’ demeleriyle imtihan edilmeden bırakılacaklarını mı sandılar?” (Ankebût 2). Hayatın ve ölümün kendisi de bir imtihan olarak tanımlanır (Mülk 2)."],
      ["Medine dönemi", "Medine'de imtihan toplumsal ve tarihsel bir boyut kazanır. Uhud yenilgisinin ardından inen âyetler, zafer ve yenilginin insanlar arasında döndürüldüğünü ve bunun müminleri arındırmak için olduğunu söyler (Âl-i İmrân 140-142). Mal ve evlat da bir fitne olarak hatırlatılır (Enfâl 28; Teğâbün 15)."]
    ],
    yakin: { ref: "Âl-i İmrân 140-141", ar: "إِنْ يَمْسَسْكُمْ قَرْحٌ فَقَدْ مَسَّ الْقَوْمَ قَرْحٌ مِثْلُهُ ۚ وَتِلْكَ الْأَيَّامُ نُدَاوِلُهَا بَيْنَ النَّاسِ وَلِيَعْلَمَ اللّٰهُ الَّذِينَ آمَنُوا وَيَتَّخِذَ مِنْكُمْ شُهَدَاءَ ۗ وَاللّٰهُ لَا يُحِبُّ الظَّالِمِينَ ۝ وَلِيُمَحِّصَ اللّٰهُ الَّذِينَ آمَنُوا وَيَمْحَقَ الْكَافِرِينَ",
      tr: "Size bir yara dokunduysa, o topluluğa da benzer bir yara dokunmuştu. O günleri insanlar arasında döndürürüz. Bu, Allah'ın iman edenleri belirlemesi ve sizden şahitler edinmesi içindir; Allah zalimleri sevmez. Bir de Allah iman edenleri arındırsın ve kâfirleri yok etsin diye.",
      incelikler: [
        ["Yaraya teselli", "Uhud'da ağır kayıp veren müminlere ilk söylenen şey, karşı tarafın da Bedir'de benzer bir yara aldığıdır. Acı yalnızca onlara özgü değildir; teselli, acının evrenselliğini hatırlatmakla başlar."],
        ["Günlerin döndürülmesi", "“Tilke'l-eyyâmu nüdâviluhâ” cümlesi, zafer ve yenilginin, güç ve zayıflığın kalıcı olmadığını, insanlar arasında el değiştirdiğini söyler. Müfessirler bu ifadeyi tarihin bir yasası olarak okumuştur."],
        ["Dört hikmet", "Âyetler yenilginin dört hikmetini sayar: Müminlerin belirmesi, şehitlerin seçilmesi, müminlerin arınması ve inkârcıların zamanla tükenmesi. Bir yenilgi, görünen kayıptan daha fazlasını taşır."]
      ] },
    tedebbur: [["“Belâ” kelimesinin “eskitmek” anlamı, seni yıpratan bir tecrübenin içinden ne çıkardığını düşünmeye nasıl davet ediyor?", "Zor bir dönemden sonra kendinde fark ettiğin bir değişikliği düşün."], ["“Günleri insanlar arasında döndürürüz” cümlesi, şu an yaşadığın iyi veya kötü bir durumun geçiciliği hakkında sana ne söylüyor?", "Güçlü olduğun bir dönemde bunun kalıcı olmadığını hatırlamanın sana ne kazandıracağını düşün."], ["Uhud'da ilk tesellinin “onlar da yara aldı” olması, başkalarının acısını hatırlamanın kendi acına bakışını nasıl değiştirebileceğini gösteriyor?", "Yaşadığın bir zorluğu, aynı zorluğu yaşayan başkalarıyla birlikte düşünmeyi dene."]] },

  anababa: {
    kok: { harf: "ب ر ر · ع ق ق", anlam: "Anne babaya iyiliği anlatan “birr” kelimesi, geniş kara parçası anlamındaki “berr” ile aynı köktendir; birr, sınırları geniş, bol ve kapsayıcı bir iyiliktir. Allah'ın isimlerinden biri de “el-Berr”dir (Tûr 28): İyiliği bol olan. Anne babaya isyanı anlatan “ukûk” kelimesi ise “kesmek, yarmak” anlamındaki kökten gelir; doğan çocuk için kesilen kurbana “akîka” denmesi de bu yüzdendir. Anne babaya isyan, kişinin kendi kökünü kesmesidir.",
      komsu: [["İhsan", "Kur'an anne babaya iyiliği çoğu zaman “ihsan” kelimesiyle emreder (İsrâ 23): Hakkı vermenin ötesinde, en güzelini yapmak."], ["Sıla-i rahim", "Akrabalık bağlarını gözetmektir; anne babaya iyiliğin akrabalara uzanan devamıdır."], ["Kavl-i kerîm", "İsrâ 23'te anne babaya söylenmesi emredilen “güzel ve onurlu söz”dür; iyiliğin dildeki karşılığıdır."]] },
    seyir: [
      ["Mekke dönemi", "Anne babaya iyiliği emreden en ayrıntılı âyetler Mekkî surelerdedir: İsrâ 23-24'teki “öf” bile dememe ve merhamet kanatlarını indirme emri, Lokmân 14-15'teki annenin zahmetinin anılması ve şirkte itaat etmeme sınırı, Ahkāf 15'teki kırk yaş duası."],
      ["Medine dönemi", "Medine'de anne babaya iyilik, tevhid emrinin hemen ardından gelen bir “misak” maddesi olarak tekrarlanır: “Allah'tan başkasına kulluk etmeyin, anne babaya iyilik edin” (Bakara 83); “Allah'a kulluk edin, O'na hiçbir şeyi ortak koşmayın ve anne babaya iyilik edin” (Nisâ 36). Kur'an'da anne babaya iyilik, tevhidden hemen sonra gelen ikinci emirdir."]
    ],
    yakin: { ref: "Ahkāf 15", ar: "وَحَمْلُهُ وَفِصَالُهُ ثَلَاثُونَ شَهْرًا ۚ حَتَّىٰ إِذَا بَلَغَ أَشُدَّهُ وَبَلَغَ أَرْبَعِينَ سَنَةً قَالَ رَبِّ أَوْزِعْنِي أَنْ أَشْكُرَ نِعْمَتَكَ الَّتِي أَنْعَمْتَ عَلَيَّ وَعَلَىٰ وَالِدَيَّ وَأَنْ أَعْمَلَ صَالِحًا تَرْضَاهُ وَأَصْلِحْ لِي فِي ذُرِّيَّتِي",
      tr: "Onun (anne karnında) taşınması ve sütten kesilmesi otuz aydır. Nihayet olgunluk çağına erişip kırk yaşına varınca şöyle der: “Rabbim! Bana ve anne babama verdiğin nimete şükretmemi ve razı olacağın salih amel işlememi ilham et. Benim için zürriyetimi de salih kıl.”",
      incelikler: [
        ["Otuz ay ve altı ay", "Hz. Osman döneminde evlendikten altı ay sonra doğum yapan bir kadının zina ile suçlanması gündeme geldiğinde, Hz. Ali bu âyeti Lokmân 14'teki “sütten kesilmesi iki yıldır” âyetiyle birlikte okumuştur: Otuz aydan yirmi dört aylık emzirme süresi çıkarılınca en kısa gebelik süresinin altı ay olduğu anlaşılır. Bu istinbat, bir kadını haksız bir cezadan kurtarmış ve fıkıhta kabul görmüştür."],
        ["Kırk yaş", "Âyet, olgunluğun zirvesi olarak kırk yaşı anar. Bu yaşta insan genellikle hem yaşlanan anne babasını hem de büyüyen çocuklarını birlikte düşünür. Dua da bu yüzden üç nesli kapsar: anne baba, kendisi ve zürriyeti."],
        ["Önce şükür", "Kırk yaşındaki insanın ilk isteği, kendisine ve anne babasına verilen nimete şükretmektir. Anne babanın aldığı nimet de çocuğun şükrünün bir konusudur; çünkü onların iyiliği çocuğa da ulaşmıştır."]
      ] },
    tedebbur: [["“Birr” kelimesinin “geniş kara” ile aynı kökten gelmesi, anne babana yaptığın iyiliğin genişliği hakkında ne düşündürüyor?", "İyiliğini belirli görevlerle sınırladığın bir alan var mı, düşün."], ["Hz. Ali'nin iki âyeti birlikte okuyarak bir kadını haksız bir cezadan kurtarması, Kur'an'ı bütüncül okumanın önemi hakkında ne söylüyor?", "Tek bir âyete dayanarak verilmiş bir hükmün, başka bir âyetle nasıl değişebileceğini düşün."], ["Kırk yaş duasındaki üç nesil (anne baba, kendin ve çocukların), senin bugünkü dualarında yer alıyor mu?", "Bu duayı kendi yaşına göre uyarlayarak bu hafta okumayı düşün."]] }
};
